import{_ as o,o as a,c as i,a3 as r}from"./chunks/framework.D3kUw6rp.js";const u=JSON.parse('{"title":"Emoji","description":"","frontmatter":{},"headers":[],"relativePath":"work/study/emoji.md","filePath":"work/study/emoji.md"}'),t={name:"work/study/emoji.md"};function n(l,e,d,c,m,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="emoji" tabindex="-1">Emoji <a class="header-anchor" href="#emoji" aria-label="Permalink to &quot;Emoji&quot;">​</a></h1><h2 id="bug" tabindex="-1">Bug <a class="header-anchor" href="#bug" aria-label="Permalink to &quot;Bug&quot;">​</a></h2><p>一句彩蛋： “Special thanks to C-Sisters🫡”。</p><p>如果此时你通过 macOS v12.6.1 以后的系统访问这篇文章，那么你可以在彩蛋的最后看到一个<code>敬礼</code>的 Emoji。倘若你通过 window 11 之前的系统访问，那么将看不到<code>敬礼</code>的 Emoji。</p><p>有点纳闷，本以为就是一句简单的文本，居然还有系统兼容问题。</p><h2 id="前世今生" tabindex="-1">前世今生 <a class="header-anchor" href="#前世今生" aria-label="Permalink to &quot;前世今生&quot;">​</a></h2><p>绘文字（日语：絵文字/えもじ emoji）是日本在无线通信中所使用的视觉情感符号，绘指图画，文字指的则是字符，可用来代表多种表情，如笑脸表示笑、蛋糕表示食物等。在中国，emoji通常叫做“小黄脸”，或者直称 Emoji。<a href="https://baike.baidu.com/item/emoji/8154456" target="_blank" rel="noreferrer">百度百科</a></p><p>所以 Emoji 就是一种特殊编码到图形的映射，它比具体语言更有通用性和传播性，比如<code>我爱你</code>只有中国人看得懂，老外需要说 <code>i love you</code>，而 👦❤️👧 则世界通用。</p><p>既然是特殊字符到某种图案的映射，那么就存在系统兼容的问题比如 A 系统用 <code>/&amp;xx</code> 代表 ❤️ ，B 系统刚好用 <code>/&amp;xx</code> 代表 🖕️。</p><p>当男生用 A 系统的手机给女孩发消息： 我❤️你 。女孩用 B 系统的手机收到的信息则是：我 🖕️ 你。一场姻缘就此断送。</p><p>于是 <a href="https://home.unicode.org/about-unicode/" target="_blank" rel="noreferrer">unicode</a> 组织就站出来了，说无规则不成方圆，由它来统一制定标准，每个图案对应什么编码都它说了算，但是具体的实现可以交给厂商只有发挥。所以 Emoji 发展成由 Unicode 决定发布哪些图案，给出大概的绘制标准，最终由各厂商实现。</p><p>比如笑脸的图标：uinicode 组织规定其编码为 U+1F600，表现上厂商可以将其实现为😊，也可以实现成😂等。但是各厂商为了<code>传意</code>的统一都会设计出比较相似的图形。</p><p>这个网站可以看某个 Emoji 对应系统的实现效果<a href="https://emojipedia.org/saluting-face/" target="_blank" rel="noreferrer">点我跳转</a>。</p><h2 id="原因" tabindex="-1">原因 <a class="header-anchor" href="#原因" aria-label="Permalink to &quot;原因&quot;">​</a></h2><p>由于一些厂商比较懒，更新不及时。unicode 组织发布了一批新表情，将 Emoji 体系升级到了 v15，但是厂商的实现还停留在 v14，那么在该系统上,由 v15 新增的新表情将显示为 ‘口’ 或乱码等。而我遇到的 bug 就是 window 系统不勤快导致的。 🫡 的表情是在 Emoji@14 版本新增的， Mac 、iPhone 都有及时跟进但是微软直到 window 11 才给予实现。</p><p><a href="https://emojipedia.org/emoji-14.0/" target="_blank" rel="noreferrer">Emoji-14.0</a></p><blockquote><p>Emoji 14.0 is the latest set of emojis recommended for release, approved September 14, 2021 alongside Unicode 14.0.</p></blockquote><blockquote><p>Additions include mixed skin tone support for 🤝 Handshake, which until now has been only default yellow on most major platforms. Other new emojis include a saluting face, a mirrored disco ball, and biting lip.</p></blockquote><blockquote><p>Support for Emoji 14.0 is now available via iOS 15.4, Google&#39;s Android 12L, and Windows 11, as well as on Twitter and Facebook.</p></blockquote><blockquote><p>Further platforms are expected to support Emoji 14.0 throughout 2022.</p></blockquote><h2 id="链接集合" tabindex="-1">链接集合 <a class="header-anchor" href="#链接集合" aria-label="Permalink to &quot;链接集合&quot;">​</a></h2><ul><li><a href="https://unicode-table.com/cn/emoji/smileys-and-emotion/#link-face-smiling" target="_blank" rel="noreferrer">Emoji 的 unicode 对照表</a></li><li><a href="https://www.emojiall.com/zh-hans/blog/419" target="_blank" rel="noreferrer">为什么不同平台 Emoji 效果不同</a></li></ul>',22)])])}const h=o(t,[["render",n]]);export{u as __pageData,h as default};
